import{_ as a,c as r,o as l,j as e,a as o}from"./chunks/framework.B63Sb1io.js";const m=JSON.parse('{"title":"ISO/OSI 参考模型和 TCP/IP 参考模型","titleTemplate":"408计算机网络","description":"综述","frontmatter":{"title":"ISO/OSI 参考模型和 TCP/IP 参考模型","titleTemplate":"408计算机网络","description":"综述","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":false,"next":false},"headers":[],"relativePath":"post/kaoyan/408/408_CN/02/408_CN_18.md","filePath":"post/kaoyan/408/408_CN/02/408_CN_18.md","lastUpdated":1756619081000}'),s={name:"post/kaoyan/408/408_CN/02/408_CN_18.md"};function n(d,t,p,i,_,c){return l(),r("div",null,t[0]||(t[0]=[e("h1",{id:"物理层接口的特性",tabindex:"-1"},[o("物理层接口的特性 "),e("a",{class:"header-anchor",href:"#物理层接口的特性","aria-label":'Permalink to "物理层接口的特性"'},"​")],-1),e("br",null,null,-1),e("p",null,"物理层考虑的是如何在连接各种计算机的传输介质上传输比特流，而不指具体的传输介质。网络中的硬件设备和传输介质的种类繁多，通信方式也各不相同。物理层应尽可能屏蔽这些差异，让数据链路层感觉不到这些差异，使其只需考虑如何实现本层的协议和服务。",-1),e("p",null,"物理层的主要任务是确定与传输介质的接口有关的一些特性： 1）机械特性。指明接口所用接线器的形状和尺寸、引脚数量和排列、固定和锁定装置等。 2）电气特性。指明在接口电缆的各条线上的电压范围、传输速率和距离限制等。 3）功能特性。指明某条线上出现的某一电平的电压的意义，以及每条线的功能。 4）过程特性，也称规程特性。指明不同功能的各种可能事件的出现顺序。",-1)]))}const f=a(s,[["render",n]]);export{m as __pageData,f as default};
